    private fun buildPaths(name: String, size: Int, paths: List<String>): ImageVector {
        val builder = ImageVector.Builder(
            name = name,
            defaultWidth = size.dp,
            defaultHeight = size.dp,
            viewportWidth = size.toFloat(),
            viewportHeight = size.toFloat(),
        )
        paths.forEach { path ->
            builder.addPath(
                pathData = PathParser().parsePathString(path).toNodes(),
                fill = SolidColor(Color.Black),
            )
        }
        return builder.build()
    }

    private fun build(name: String, size: Int, path: String): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = size.dp,
            defaultHeight = size.dp,
            viewportWidth = size.toFloat(),
            viewportHeight = size.toFloat(),
        ).addPath(
            pathData = PathParser().parsePathString(path).toNodes(),
            fill = SolidColor(Color.Black),
        ).build()
}
